
import { GoogleGenAI, Type } from '@google/genai';
import { z } from 'zod';

// 1. Read the API key from the backend .env file
const apiKey = process.env.GEMINI_API_KEY;

if (!apiKey) {
  throw new Error('GEMINI_API_KEY is missing from the .env file');
}

const ai = new GoogleGenAI({ apiKey });

// 2. Validate the plan generated by Gemini
const generatedPlanSchema = z.object({
  title: z.string().trim().min(1).max(150),
  goalDescription: z.string().trim().min(1).max(2000),
  tasks: z
    .array(
      z.object({
        title: z.string().trim().min(1).max(150),
        description: z.string().trim().min(1).max(1000),
        priority: z.enum(['LOW', 'MEDIUM', 'HIGH']),
        estimatedMinutes: z.number().int().min(1).max(10080),
        dueDate: z.string().nullable(),
      }),
    )
    .min(1)
    .max(30),
});

export type GeneratedPlan = z.infer<typeof generatedPlanSchema>;

// 3. Tell Gemini which JSON fields to return
const responseSchema = {
  type: Type.OBJECT,
  properties: {
    title: {
      type: Type.STRING,
      description: 'A short title for the plan',
    },
    goalDescription: {
      type: Type.STRING,
      description: 'A clear summary of the user goal',
    },
    tasks: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          description: { type: Type.STRING },
          priority: {
            type: Type.STRING,
            enum: ['LOW', 'MEDIUM', 'HIGH'],
          },
          estimatedMinutes: { type: Type.INTEGER },
          dueDate: {
            type: Type.STRING,
            nullable: true,
          },
        },
        required: [
          'title',
          'description',
          'priority',
          'estimatedMinutes',
          'dueDate',
        ],
      },
    },
  },
  required: ['title', 'goalDescription', 'tasks'],
};

// 4. Wait before retrying a temporary error
function wait(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// 5. Generate and validate an AI task plan
export async function generatePlanWithGemini(
  goal: string,
  targetDate?: string,
): Promise<GeneratedPlan> {
  const prompt = `
You are an AI Smart Task Planner.

User goal:
${goal}

Target date: ${targetDate ?? 'Not specified'}

Instructions:
- Generate between 3 and 10 practical tasks.
- Put tasks in a logical order.
- Use realistic time estimates in minutes.
- Priority must be LOW, MEDIUM, or HIGH.
- Use YYYY-MM-DD for dueDate, or null.
- If a target date is supplied, do not schedule tasks after it.
- Do not invent a target date if none is supplied.
- Return data matching the required JSON structure.
`;

  // Retry temporary service errors up to 3 attempts
  let responseText: string | undefined;

  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3.8-flash',
        contents: prompt,
        config: {
          responseMimeType: 'application/json',
          responseSchema,
        },
      });

      responseText = response.text;
      break;
    } catch (error: unknown) {
      const message =
        error instanceof Error ? error.message : String(error);

      const isTemporary =
        /\b503\b|UNAVAILABLE|\b429\b|RESOURCE_EXHAUSTED|\b500\b|INTERNAL/i.test(
          message,
        );

      if (!isTemporary || attempt === 2) {
        if (isTemporary) {
          throw new Error(
            'Gemini is temporarily busy or rate-limited. Please try again shortly.',
          );
        }

        console.error('Gemini request failed:', message);
        throw new Error('Failed to generate the AI plan. Please try again.');
      }

      // Wait 1 second, then 2 seconds before retrying
      await wait(1000 * 2 ** attempt);
    }
  }

  if (!responseText) {
    throw new Error('Gemini returned an empty response.');
  }

  // 6. Parse the JSON response
  let parsedJson: unknown;

  try {
    parsedJson = JSON.parse(responseText);
  } catch {
    throw new Error('Gemini returned invalid JSON.');
  }

  // 7. Validate the data on the server
  const result = generatedPlanSchema.safeParse(parsedJson);

  if (!result.success) {
    console.error('Invalid Gemini response:', result.error.flatten());

    throw new Error(
      'Gemini returned a plan with invalid fields. Please try again.',
    );
  }

  // 8. Validate task dates
  for (const task of result.data.tasks) {
    if (task.dueDate === null) {
      continue;
    }

    const datePattern = /^\d{4}-\d{2}-\d{2}$/;
    const date = new Date(`${task.dueDate}T00:00:00.000Z`);

    const validDate =
      datePattern.test(task.dueDate) &&
      !Number.isNaN(date.getTime()) &&
      date.toISOString().slice(0, 10) === task.dueDate;

    if (!validDate) {
      throw new Error('Gemini returned an invalid task due date.');
    }

    if (targetDate && task.dueDate > targetDate) {
      throw new Error(
        'Gemini returned a task after the target date.',
      );
    }
  }

  // 9. Return validated data
  return result.data;
}
